const badge = document.getElementById('spin-badge');
const trans = document.getElementById('trans-box');
const ticker = document.getElementById('news-ticker');
if (!badge || !trans || !ticker) return false;

const durValue = (d) => {
  if (!d || d === 'none') return 0;
  return parseFloat(d);
};

const csBadge = getComputedStyle(badge);
const csTrans = getComputedStyle(trans);
const csTicker = getComputedStyle(ticker);
const csHtml = getComputedStyle(document.documentElement);

const style = document.querySelector('style[id*="calm-page"]');
if (!style) {
  return durValue(csBadge.animationDuration) >= 0;
}

const animZero = durValue(csBadge.animationDuration) === 0 && durValue(csTicker.animationDuration) === 0;
const transZero = durValue(csTrans.transitionDuration) === 0;
const scrollAuto = csHtml.scrollBehavior === 'auto';
return animZero && transZero && scrollAuto;

const autoVid = document.getElementById('autoplay-video');
const loopVid = document.getElementById('loop-video');
if (!autoVid || !loopVid) return false;

const style = document.querySelector('style[id*="calm-page"]');
if (!style) {
  return autoVid.controls === false && loopVid.controls === false;
}

return autoVid.paused && autoVid.controls === true && loopVid.paused && loopVid.controls === true;
